-- Verificação legal de 17/10/2026 (pesquisas-legais/verif-2026-10-17-simples-mei [D16][D18]): a Res. CGSN 190/2026
-- (DOU 10/08/2026, efeitos em 01/01/2027) regulou o que a semente dizia "não regulamentado" e mudou a fonte do SIMEI.
-- DEFIS: mesma vigência e valor da sn2-obr-defis-simples (prazo 31/03/2027), só a fonte muda — supersedes (linha publicada
-- não se edita). A ambiguidade A1 (DEFIS × PGDAS-D para o ano-calendário 2026) fica com o dono/contador.
INSERT OR IGNORE INTO "legal_parameters" ("id","tabela","chave","discriminador","valorInt","valorTexto","valorJson","fonte","fonteUrl","fonteSha256","vigenteDesde","vigenteAte","status","supersedesId","motivo","proposedById","publishedById","publishedAt","createdAt") VALUES ('sn7-obr-defis-simples', 'OBRIGACAO_REGIME', 'DEFIS', 'SIMPLES', NULL, NULL, '{"statusBase":"OBRIGATORIA","condicoes":[],"inativa":{"status":"OBRIGATORIA","fonte":"Res. CGSN 140/2018 art. 72 caput (sem exceção para a inativa)"}}', 'Res. CGSN 140/2018 art. 72 caput e § 1º (anual, até 31/03 do ano seguinte) até o ano-calendário 2026; o art. 72 é revogado em 01/01/2027 (Res. CGSN 190/2026 art. 8º XXI; efeitos pelo art. 9º) e as informações socioeconômicas e fiscais do ano-calendário anterior passam ao PGDAS-D, de janeiro a março (Res. CGSN 140/2018 art. 38-B, incl. Res. CGSN 190/2026). Vale até 31/03/2027; se as do ano-calendário 2026 vão na DEFIS ou no PGDAS-D do art. 38-B está em aberto (ambiguidade A1 do dossiê, pergunta ao contador)', 'https://normasinternet2.receita.fazenda.gov.br/api/consulta-externa/ato/152832/visao/multivigente', 'f6b9c4986b051322caeec2eeb7e467ea38ae6d4aa2d8b16a5c7d95cbfca0317c', '2018-01-01', '2027-03-31', 'PUBLISHED', 'sn2-obr-defis-simples', 'Verificação legal de 17/10/2026 (pesquisas-legais/verif-2026-10-17-simples-mei, conclusão itens 3 e 4); dono, chat, 2026-10-17: "Já dispara as correções que ainda não começaram"', 'migracao:VERIF-LEGAL-2026-10-17', 'migracao:VERIF-LEGAL-2026-10-17', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
-- SIMEI ICMS/ISS 2027–2028: mesmo valor (R$ 1,00 / R$ 5,00), fonte nova. As linhas sn1-simei-icms/iss seguem certas para
-- 2018–2026 (art. 101 II/III em vigor até 31/12/2026): não são substituídas — a linha de vigenteDesde mais recente vence,
-- como as sn5 de 2029+ já fazem.
INSERT OR IGNORE INTO "legal_parameters" ("id","tabela","chave","discriminador","valorInt","valorTexto","valorJson","fonte","fonteUrl","fonteSha256","vigenteDesde","vigenteAte","status","supersedesId","motivo","proposedById","publishedById","publishedAt","createdAt") VALUES ('sn7-simei-icms-2027', 'SIMEI_VALOR', 'ICMS', NULL, 100, NULL, NULL, 'Res. CGSN 140/2018 art. 101 V e Anexo XIII (red. Res. CGSN 190/2026 art. 1º; Anexo XIII incl. pelo art. 7º), valor de 2027 e 2028; o art. 101 II é revogado pelo art. 8º XXVII (efeitos pelo art. 9º)', 'https://normasinternet2.receita.fazenda.gov.br/api/consulta-externa/ato/152832/anexo/85784', '6a7e99859482d0b2d202dfb68f89aea2dd72ced2a01c4be95bdf8c086c50c1c5', '2027-01-01', '2028-12-31', 'PUBLISHED', NULL, 'Verificação legal de 17/10/2026 (pesquisas-legais/verif-2026-10-17-simples-mei, conclusão itens 3 e 4); dono, chat, 2026-10-17: "Já dispara as correções que ainda não começaram"', 'migracao:VERIF-LEGAL-2026-10-17', 'migracao:VERIF-LEGAL-2026-10-17', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
